/* Wet Ape 7 by danilppzz — https://uiverse.io/danilppzz/wet-ape-7 */
.button {
  background-color: #292929;
  border: 1px solid #3e3e3e;
  border-radius: 8px;
  color: #fff;
  padding: 14px 24px;
  text-decoration: none;
  font-size: 16px;
  margin: 12px 14px;
  cursor: pointer;
}

.button:hover {
  border: 1px solid #fff;
}
